set_temp_variable = { mengele_event016_native_component_recorded = constant:brilliant_scientist_value.zero }
set_temp_variable = { mengele_event016_requested_stage = constant:brilliant_scientist_project_stage.prototype }
set_temp_variable = { mengele_event016_native_component_index = constant:brilliant_scientist_value.zero }
if = {
	limit = {
		brilliant_scientist_mengele_singularity_component_native_output_is_authentic = yes
		brilliant_scientist_mengele_project_stage_receipt_is_empty = yes
	}
	brilliant_scientist_mengele_initialize_project_stage_receipts = yes
	brilliant_scientist_mengele_initialize_singularity_component_provenance = yes
	if = {
		limit = { NOT = { is_in_array = { array = mengele_event016_singularity_component_entries value = brilliant_scientist_singularity_component } } }
		add_to_array = { array = mengele_event016_singularity_component_entries value = brilliant_scientist_singularity_component }
		set_variable = { mengele_event016_singularity_component_count = mengele_event016_singularity_component_entries^num }
		if = { limit = { check_variable = { var = brilliant_scientist_singularity_component value = constant:brilliant_scientist_singularity_component.command_core compare = equals } } set_country_flag = mengele_event016_singularity_command_core_completed }
		else_if = { limit = { check_variable = { var = brilliant_scientist_singularity_component value = constant:brilliant_scientist_singularity_component.power_link compare = equals } } set_country_flag = mengele_event016_singularity_power_link_completed }
		else_if = { limit = { check_variable = { var = brilliant_scientist_singularity_component value = constant:brilliant_scientist_singularity_component.containment_lattice compare = equals } } set_country_flag = mengele_event016_singularity_containment_lattice_completed }
		else_if = { limit = { check_variable = { var = brilliant_scientist_singularity_component value = constant:brilliant_scientist_singularity_component.temporal_authenticator compare = equals } } set_country_flag = mengele_event016_singularity_temporal_authenticator_completed }
		else_if = { limit = { check_variable = { var = brilliant_scientist_singularity_component value = constant:brilliant_scientist_singularity_component.delivery_architecture compare = equals } } set_country_flag = mengele_event016_singularity_delivery_architecture_completed }
		else_if = { limit = { check_variable = { var = brilliant_scientist_singularity_component value = constant:brilliant_scientist_singularity_component.fail_deadly_governor compare = equals } } set_country_flag = mengele_event016_singularity_fail_deadly_governor_completed }
		set_temp_variable = { mengele_event016_native_component_index = brilliant_scientist_singularity_component }
		subtract_from_temp_variable = { mengele_event016_native_component_index = constant:brilliant_scientist_value.one }
		set_variable = { mengele_event016_singularity_component_mode_entries^mengele_event016_native_component_index = mengele_event016_native_component_mode }
		set_temp_variable = { mengele_event016_native_component_recorded = constant:brilliant_scientist_value.one }
	}
	# An exact duplicate may retry missing Prototype, preserving first mode.
	brilliant_scientist_mengele_try_settle_singularity_native_prototype = yes
}
brilliant_scientist_mengele_clear_singularity_component_selectors = yes

